// ReproduceCode.jsx
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import { NumberInput } from 'carbon-components-react';

function App() {
  return (
    <div style={{ padding: '2rem' }}>
      {/* 1) Disabled state violation */}
      <NumberInput
        id="disabled-number-input"
        label="Number input (disabled)"
        helperText="This input is disabled"
        min={0}
        max={100}
        step={10}
        value={50}
        disabled
      />

      <hr style={{ margin: '2rem 0' }} />

      {/* 2) Validation/label mismatch violation */}
      <NumberInput
        id="validation-number-input"
        label="Number Input label"
        helperText="Optional helper text."
        min={0}
        max={100}
        step={10}
        value={50}
        invalid
        invalidText="Number is not valid"
        hideLabel             // visually hides the label
        // ariaLabel defaults to "Numeric input field with increment and decrement buttons"
      />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
